patch:
diff --git a/sql/sql_lex.cc b/sql/sql_lex.cc
index dd51ebff5c4f..e57fc39e64ad 100644
--- a/sql/sql_lex.cc
+++ b/sql/sql_lex.cc
@@ -1704,6 +1704,8 @@ void trim_whitespace(const CHARSET_INFO *cs, LEX_STRING *str)
   while ((str->length > 0) && (my_isspace(cs, str->str[str->length-1])))
   {
     str->length --;
+    /* set trailing spaces to 0 as there're places that don't respect length */
+    str->str[str->length]= 0;
   }
 }

diff --git a/sql/sql_yacc.yy b/sql/sql_yacc.yy
index 1d39610844db..a0c06c78c01e 100644
--- a/sql/sql_yacc.yy
+++ b/sql/sql_yacc.yy
@@ -13886,6 +13886,12 @@ user:
             $$->uses_identified_by_password_clause= false;
             $$->uses_authentication_string_clause= false;

+            /*
+              Trim whitespace as the values will go to a CHAR field
+              when stored.
+            */
+            trim_whitespace(system_charset_info, &$$->user);
+
             if (check_string_char_length(&$$->user, ER(ER_USERNAME),
                                          USERNAME_CHAR_LENGTH,
                                          system_charset_info, 0))
@@ -13917,6 +13923,12 @@ user:
               the character set is utf8.
             */
             my_casedn_str(system_charset_info, $$->host.str);
+            /*
+              Trim whitespace as the values will go to a CHAR field
+              when stored.
+            */
+            trim_whitespace(system_charset_info, &$$->user);
+            trim_whitespace(system_charset_info, &$$->host);
           }
         | CURRENT_USER optional_braces
           {
